#!/bin/sh
# Build gekko as an Erlang shipment and install a standalone `gekko` launcher on PATH.
# Usage: scripts/install.sh [bin_dir]   (default: ~/.local/bin)
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
BIN_DIR="${1:-$HOME/.local/bin}"
INSTALL_DIR="${GEKKO_INSTALL_DIR:-${XDG_DATA_HOME:-$HOME/.local/share}/gekko}"

cd "$ROOT"
gleam export erlang-shipment

mkdir -p "$INSTALL_DIR"
rm -rf "$INSTALL_DIR/erlang-shipment"
cp -R "$ROOT/build/erlang-shipment" "$INSTALL_DIR/erlang-shipment"

mkdir -p "$BIN_DIR"
cat > "$BIN_DIR/gekko" <<EOF
#!/bin/sh
# Generated by $ROOT/scripts/install.sh
exec "$INSTALL_DIR/erlang-shipment/entrypoint.sh" run "\$@"
EOF
chmod +x "$BIN_DIR/gekko"
echo "Installed $BIN_DIR/gekko (runtime copied to $INSTALL_DIR/erlang-shipment)"
